import java.util.Scanner; public class TestClass { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int M = sc.nextInt(); int N = sc.nextInt(); int[] C = new int[M]; for (int i = 0; i < M; i++) { C[i] = sc.nextInt(); } long[] dp = new long[N + 1]; dp[0] = 1; int MOD = 1000000007; for (int i = 0; i < M; i++) { int cap = C[i]; for (int j = cap; j <= N; j++) { dp[j] = (dp[j] + dp[j - cap]) % MOD; } } System.out.println(dp[N]); } }